package stream

import "strings"

// Class is the playback classification of one item (spec "Playback
// classification"): exactly one of the four values below. Derived per item
// from stored ffprobe facts — never stored itself (D-2), never taken from
// client input.
type Class string

// The four playback classes, spelled exactly as the spec names them.
const (
	// ClassDirect: browser-decodable codec in a browser-acceptable container —
	// serve the original bytes; no transform work is ever spent.
	ClassDirect Class = "direct"
	// ClassPack: browser-decodable codec in a hostile container (MKV+h264/AAC
	// is canonical) — remux-only packaging is permitted.
	ClassPack Class = "pack"
	// ClassOptIn: a codec many targets cannot decode (HEVC/AC-3) — packable
	// only while the opt-in codec knob is enabled. While the knob is at its
	// default (off), Classify returns ClassDirectOnly for these items instead.
	ClassOptIn Class = "opt_in"
	// ClassDirectOnly: no browser can decode the stream and remuxing cannot
	// change that (>8-bit h264, unknown codecs, undecodable audio) — never
	// packaged; direct floor only.
	ClassDirectOnly Class = "direct_only"
)

// Classify derives an item's playback Class from the verbatim ffprobe facts
// stored in its document (the parsed "ffprobe" blob: {"streams": [...],
// "format": {...}, ...}) and from the opt-in codec knob. Pure (INV1): the
// inputs are never mutated and nothing is read or persisted. Fail-safe
// (INV2): absent facts, a missing video stream, or unrecognized codecs all
// classify ClassDirectOnly. The knob is folded in (INV3): opt-in codecs
// classify ClassOptIn only while optInCodecs is true, ClassDirectOnly
// otherwise — callers never re-implement the gate. Every class keeps the
// direct floor (INV4).
func Classify(ffprobe map[string]any, optInCodecs bool) Class {
	video, audio := videoAudioStreams(ffprobe["streams"])
	if video == nil {
		return ClassDirectOnly // no decidable picture (audio-only file, empty facts)
	}

	// Video: 8-bit h264 and the WebM/AV1 family are browser-decodable; >8-bit
	// h264 and any unrecognized codec are ClassDirectOnly unconditionally
	// (remuxing cannot make them decodable — the reason the class exists, D-2).
	videoOptIn := false
	switch streamCodec(video) {
	case "h264":
		if streamTenBit(video) {
			return ClassDirectOnly // High10: burns budget for an unplayable stream
		}
	case "vp8", "vp9", "av1":
	case "hevc", "h265":
		videoOptIn = true
	default:
		return ClassDirectOnly
	}

	// Audio: the pack lane maps every audio track through (D-3: -map 0:a), so
	// the WORST audio stream decides — one undecodable track (DTS, TrueHD)
	// makes the remux unplayable (ClassDirectOnly); one opt-in track
	// (AC-3/E-AC-3) gates the whole item on the knob.
	audioOptIn := false
	for _, a := range audio {
		switch streamCodec(a) {
		case "aac", "mp3", "opus", "vorbis", "flac":
			// browser-decodable; keep judging the remaining tracks
		case "ac3", "eac3":
			audioOptIn = true
		default:
			return ClassDirectOnly
		}
	}

	// Fold the knob: an opt-in-gated item is packable only while it is enabled
	// (INV3 — while off, it behaves exactly as direct_only).
	if videoOptIn || audioOptIn {
		if !optInCodecs {
			return ClassDirectOnly
		}
		return ClassOptIn
	}
	if containerAcceptable(ffprobe) {
		return ClassDirect
	}
	return ClassPack
}

// videoAudioStreams splits the ffprobe "streams" array into the first video
// stream (the pack lane carries exactly one — D-3: -map 0:v:0) and the audio
// streams, in file order. A non-array or empty value yields (nil, nil).
func videoAudioStreams(v any) (video map[string]any, audio []map[string]any) {
	list, ok := v.([]any)
	if !ok {
		return nil, nil
	}
	for _, s := range list {
		m, ok := s.(map[string]any)
		if !ok {
			continue
		}
		switch m["codec_type"] {
		case "video":
			if video == nil {
				video = m
			}
		case "audio":
			audio = append(audio, m)
		}
	}
	return video, audio
}

// streamCodec reads a stream's codec_name, lowercased (ffprobe is already
// lowercase, but facts are verbatim — never trust the source's casing).
func streamCodec(s map[string]any) string {
	name, _ := s["codec_name"].(string)
	return strings.ToLower(strings.TrimSpace(name))
}

// streamTenBit reports whether a video stream exceeds 8 bits per sample:
// an explicit bits_per_raw_sample > 8, or a 10-bit pixel format
// (yuv420p10le, p010le, ...). This is the High10 mark — h264 remuxed into
// any container stays undecodable (D-2).
func streamTenBit(s map[string]any) bool {
	if bits, ok := s["bits_per_raw_sample"].(float64); ok && bits > 8 {
		return true
	}
	pix, _ := s["pix_fmt"].(string)
	return strings.Contains(pix, "10")
}

// containerAcceptable reports whether the probed container is one browsers
// accept natively (the MP4 family), read from the ffprobe format blob's
// format_name. The matroska family reads hostile INCLUDING its "webm" tag:
// ffprobe's shared demuxer reports "matroska,webm" for MKV and WebM alike, so
// the tag cannot disambiguate — and an MKV misread as acceptable would lose
// its packaging lane (the spec's canonical pack case), while a WebM misread
// as hostile merely stays permitted to package, floor intact. An absent or
// unreadable format also reads hostile (fail-safe, INV2): mis-packaging a
// genuinely direct item wastes budget; failing to package an exotic one
// loses nothing — the direct floor holds either way.
func containerAcceptable(ffprobe map[string]any) bool {
	format, _ := ffprobe["format"].(map[string]any)
	name, _ := format["format_name"].(string)
	name = strings.ToLower(name)
	for _, good := range []string{"mp4", "m4a", "m4v", "mov"} {
		if strings.Contains(name, good) {
			return true
		}
	}
	return false
}
